import numpy as np
one=np.ones_like(t)
base={'1':one,'t':t,'1/t':1/t,'sqrt':np.sqrt(t),'log':np.log(t),'exp-t':np.exp(-t),'t2':t**2,'1/sqrt':1/np.sqrt(t),'exp-2t':np.exp(-2*t),'texp':t*np.exp(-t),'1/t2':1/t**2}
import itertools
names=list(base)
res=[]
def fit(sel):
    cols=[]
    for Aj in [one,A,A**2]:
        for s in sel:
            cols.append(base[s]*Aj)
    M=np.array(cols).T
    co,_,_,_=np.linalg.lstsq(M,dA_dt,rcond=None)
    r=dA_dt-M@co
    return np.mean(r**2)/np.var(dA_dt),co
best=[]
for k in [3,4,5]:
    for sel in itertools.combinations(names,k):
        e,_=fit(sel)
        best.append((e,sel))
best.sort()
for b in best[:8]: print(b)

